"use client";
import Navbar from "/src/components/Navbar";
import Hero from "/src/components/Hero";
import ProductShowcase from "/src/components/ProductShowcase";
import Categories from "/src/components/Categories";
import Newsletter from "/src/components/Newsletter";
import Footer from "/src/components/Footer";

export default function App() {
  return (
    <div className="min-h-screen bg-gray-50">
      <Navbar />
      <main>
        <Hero />
        <ProductShowcase />
        <Categories />
        <Newsletter />
      </main>
      <Footer />
    </div>
  );
}

export default function Hero() {
  return (
    <section className="bg-gradient-to-r from-indigo-500 to-purple-600 text-white py-20">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 text-center">
        <h2 className="text-4xl md:text-6xl font-bold mb-6">Discover the Best Deals</h2>
        <p className="text-xl mb-8 max-w-2xl mx-auto">
          Shop the latest trends in fashion, electronics, and more at unbeatable prices.
        </p>
        <button className="bg-white text-indigo-600 font-bold py-3 px-6 rounded-full hover:bg-gray-100 transition">
          Shop Now
        </button>
      </div>
    </section>
  );
}

const products = [
  {
    id: 1,
    name: "Wireless Headphones",
    price: "$99.99",
    image: "https://via.placeholder.com/300x200",
  },
  {
    id: 2,
    name: "Smart Watch",
    price: "$149.99",
    image: "https://via.placeholder.com/300x200",
  },
  {
    id: 3,
    name: "Bluetooth Speaker",
    price: "$79.99",
    image: "https://via.placeholder.com/300x200",
  },
  {
    id: 4,
    name: "Laptop Backpack",
    price: "$49.99",
    image: "https://via.placeholder.com/300x200",
  },
];

export default function ProductShowcase() {
  return (
    <section className="py-12 bg-white">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <h2 className="text-3xl font-bold text-gray-800 mb-8">Featured Products</h2>
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
          {products.map((product) => (
            <div key={product.id} className="bg-gray-100 rounded-lg overflow-hidden shadow-sm hover:shadow-md transition">
              <img
                src={product.image}
                alt={product.name}
                className="w-full h-48 object-cover"
              />
              <div className="p-4">
                <h3 className="font-semibold text-lg text-gray-800">{product.name}</h3>
                <p className="text-gray-600 mt-2">{product.price}</p>
                <button className="mt-4 w-full bg-indigo-600 text-white py-2 rounded hover:bg-indigo-700 transition">
                  Add to Cart
                </button>
              </div>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}

const categories = [
  { id: 1, name: "Electronics", icon: "📱" },
  { id: 2, name: "Fashion", icon: "👕" },
  { id: 3, name: "Home & Garden", icon: "🏠" },
  { id: 4, name: "Sports", icon: "⚽" },
];

export default function Categories() {
  return (
    <section className="py-12 bg-gray-50">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <h2 className="text-3xl font-bold text-gray-800 mb-8">Shop by Category</h2>
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
          {categories.map((category) => (
            <div
              key={category.id}
              className="bg-white p-6 rounded-lg shadow-sm hover:shadow-md transition text-center"
            >
              <div className="text-4xl mb-4">{category.icon}</div>
              <h3 className="font-semibold text-lg text-gray-800">{category.name}</h3>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}

